/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Quarry",
  theme: defineTheme({
    colors: {
      background: "#0e0f10",
      foreground: "#eceae4",
      primary: "#d4f25a",
      primaryForeground: "#0e0f10",
      border: "#2b2d30",
      muted: "#a3a199",
      surface: "#17191b",
      accent: "#c2e040",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'JetBrains Mono', Menlo, Consolas, monospace" },
    fontSizes: { body: 15, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 12, lg: 20, xl: 32 },
    radii: { sm: 4, md: 8 },
    elements: {
      Heading: {
        fontWeight: 500,
        by: {
          level: {
            1: { fontSize: 28, lineHeight: 1.15 },
            2: { fontSize: 21, lineHeight: 1.25 },
            3: { fontSize: 17, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/quarry/logo.png", width: 480, height: 120, alt: "Quarry" },
  address: "88 Kiln Road, Austin",
  links: { site: "https://quarry.example", domains: ["quarry.example", "*.quarry.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "JetBrains Mono", src: "https://hyperelements.dev/generated/gallery/assets/fonts/JetBrainsMono-500.ttf", weight: 500, style: "normal" },
  ],
};
// brand: end

