          <Heading level={2}>$378.00 USD due March 31</Heading>
          <Text>
            <Link href={`${brand.links.site}/invoices/pay/A1B2C3D4-0017`} style={{ color: token("colors.primary"), textDecoration: "underline" }}>
              Pay online
