    colors: {
      background: "#f5f0e6",
      foreground: "#1d1b18",
      primary: "#a8331f",
      primaryForeground: "#ffffff",
      border: "#d6cdbd",
      muted: "#625c52",
      surface: "#fffdf8",
      accent: "#e9b9a8",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'Source Serif 4', Georgia, 'Times New Roman', serif" },
    fontSizes: { body: 17, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 6, sm: 12, md: 20, lg: 32, xl: 56 },
    radii: { sm: 0, md: 0 },
    elements: {
      Heading: {
        fontWeight: 600,
        by: {
          level: {
            1: { fontSize: 34, lineHeight: 1.15 },
            2: { fontSize: 25, lineHeight: 1.25 },
            3: { fontSize: 20, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/pith/logo.png", width: 480, height: 120, alt: "Pith" },
  address: "9 Press Row, Portland",
  links: { site: "https://pith.example", domains: ["pith.example", "*.pith.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "Source Serif 4", src: "https://hyperelements.dev/generated/gallery/assets/fonts/SourceSerif4-600.ttf", weight: 600, style: "normal" },
  ],
};
// brand: end

// The design
const meta = {
  label: "Open Graph card",
  description: "A link preview, 1200 by 630: the title fitted to three lines, the brand's logo and site, and shapes in its colors",
};

function OgCard() {
  return (
    <Canvas
      width={1200}
      height={630}
      fonts={brand.fonts}
      lang={brand.lang ?? "en"}
      dir={brand.dir}
      theme={brand.theme}
    >
      <Row style={{ height: 630, gap: 40 }}>
        <Column style={{ width: 820, height: 630, padding: [64, 0, 64, 72], justifyContent: "space-between" }}>
          <Image
            src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }}
            alt={brand.logo.alt}
            style={{ width: 200 }}
          />
          <Heading level={1} fit={{ sizes: [68, 60, 52, 46, 40], maxLines: 3 }} style={{ lineHeight: 1.08 }}>
            How we cut our build times in half without changing a line of product code
          </Heading>
          <Text style={{ fontSize: 26, color: token("colors.muted") }}>{new URL(brand.links.site).host}</Text>
        </Column>
        <Svg width={340} height={630} viewBox="0 0 340 630">
          <Circle cx={250} cy={120} r={150} style={{ fill: token("colors.primary") }} />
          <Circle cx={120} cy={420} r={90} style={{ fill: token("colors.accent") }} />
          <Circle cx={300} cy={560} r={120} style={{ fill: token("colors.surface") }} />
        </Svg>
      </Row>
    </Canvas>
  );
}

export default OgCard;

