          <Circle cx={860} cy={180} r={220} style={{ fill: token("colors.accent") }} />
          <Circle cx={760} cy={560} r={150} style={{ fill: token("colors.surface") }} />
          <Circle cx={120} cy={600} r={70} style={{ fill: token("colors.border") }} />
